quests[46498] = { id = 46498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fearless Combatant's Felweave Armor" }
quests[46499] = { id = 46499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiders, Huh?", description = "I feel like they're still crawling all over me. I squished one egg and all of a sudden I'm covered head to toe in baby spiders.\n\n<Shivers>.\n\nThat treasure is just sitting there now. The next guy better not be arachnaphlipic... arachnaphonetic? Arachniphant? Afraid of spiders!", progress = "I'm always lookin' for more treasure!", completion = "Oh, look here! You went and got that treasure! Hey... You still got a spider on your shoulder.\n\nLets see what fantastic treasure you brought me... This is it? This is worthless! Here you keep it.\n\nTough break, kid. Keep at it.", objectives = "Look for the rumored treasure in the Creeping Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46500] = { id = 46500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb of Sargeras: Legend of the Deep" }
quests[46501] = { id = 46501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Robbin'", description = "I am not a grave robber, but is it technically grave robbing if the treasure is sitting on a field of bones? It's not like it's buried or nothin'. I'm just gonna sit this one out, just in case.", progress = "I'm always lookin' for more treasure!", completion = "You found a key in a chest? Nothing else?\n\nI'm guessing the last guy took all the goods, then accidentally locked the key in the chest. So, you just found a key to a chest that you've already looted. Fantastic work... And people say I suck at this job.", objectives = "Look for the rumored treasure in the Soul Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
