quests[46509] = { id = 46509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomb Raidering", description = "I said to myself over and over, \"Don't go near the citadel. Don't go near the citadel.\" But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!", progress = "I'm always lookin' for more treasure!", completion = "Did you bother to read the label on this potion? I'm going to assume, no. You may find some sucker who will pay you for it.\n\nBetter luck next time kid.", objectives = "Look for the rumored treasure outside the Tomb of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46510] = { id = 46510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Graveyard", description = "I haven't told you that I was part of the original landing party when we lost almost everything.  I don't care what treasure is left there, I'll never go back to that beach. Never.", progress = "I'm always lookin' for more treasure!", completion = "It's... Wet. This thing is most likely worthless now.\n\nIs there a good piece of treasure on this cursed island? I may not be the brightest tool in the bag, but I'm starting to think this place doesn't really fit my \"chance of death versus treasure\" ratio.", objectives = "Look for the rumored treasure deep in the Forlorn Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46511] = { id = 46511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Treasure Hunters", description = "I have a feeling you're just using me for tips on where all the best treasure is. From now on I'm naga tell you anything. Did I say, \"naga\" just then? I meant to say, I'm not gonna to tell you naga. I mean nada! Darn it!\n\nOkay. Seems you got me on this one. I'll tell you what, fetch me whatever is in that chest near those naga freaks and I'll make it worth your while.", progress = "You fetch that treasure yet?", completion = "This is it? You sure you didn't find anything else? Like a giant pile of gold on top of a statue made of diamonds which was holding a scroll listing the combination to the vault in Ironforge? That would have been pretty sweet.\n\nOh well. I can make this into a paper weight or throw it at a squirrel.\n\nCome back tomorrow, I'll have another job for you.", objectives = "Look for the rumored treasure on the Felrage Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
